        int time = 0;
        deq.push(1);

        while(!deq.isEmpty()) {
            int top = deq.peek();
            if (find[top] == 0) find[top] = ++time;

            int j;
            for (j = 1; j <= n; j++) {
                if (g[top][j] == 1 && find[j] == 0) {
                    deq.push(j);
                    find[j] = ++time;
                    break;
                }
            }
            if (j == n + 1) {
                deq.pop();
                finish[top] = ++time;
            }

            if (deq.isEmpty()) {
                for (int i = 1; i <= n; i++) {
                    if (find[i] == 0) {
                        deq.push(i);
                        find[i] = ++time;
                        break;
                    }
                }
            }
        }

